"""Stage one reviewed append on existing four IDs. Coordinator does Drive I/O."""
from pathlib import Path
from datetime import datetime,timezone
import argparse,json,zipfile,hashlib,re
HERE=Path(__file__).resolve().parent
RUN=HERE/'cloud_publication/sgk_finish_20261020'
def sha(b):return hashlib.sha256(b).hexdigest()
def read(p):return json.loads(p.read_text('utf-8'))
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,sort_keys=True,indent=2)+'\n',encoding='utf-8')
def main(link_id):
    receipt=read(RUN/'bundle_remote_verified.json');assert receipt['fresh_raw_verified'] and receipt['all_bytes_equal']
    state=read(RUN/'prewrite_state.json');chat=read(RUN/'prewrite_chat.json');report=read(RUN/'release/audit_report.json')
    assert state['accepted_cases']==1629597 and state['training_chat_rows']==6501044
    assert chat['chat_rows']==6501044 and not any(r['run_id']=='sgk_finish_20261020' for r in state.get('sgk_finish_runs',[]))
    now=datetime.now(timezone.utc).isoformat();profile=read(RUN/'root_evidence/reconnected_duymanh_controls.json')['profile'];profile=dict(profile,link_id=link_id,binding='CURRENT_CONNECTOR_PROFILE_REVERIFIED_AFTER_CODEX_ACCOUNT_SWITCH')
    ref=dict(run_id='sgk_finish_20261020',bundle=receipt,cases=report['cases'],chat_rows=report['chat_rows'],by_grade=report['by_grade'],source_member='data/release/accepted_cases.jsonl',chat_member='data/release/accepted_chat.jsonl',token_audit_member='data/release/token_audit.json',portable_checkpoint_member='data/portable_resume/portable_checkpoint.json',discovered_catalog_member='data/portable_resume/member_catalog_discovered.json',acceptance_status='ACCEPTED_VALIDATED_OWNER_PREAUTHORIZED',new_human_attestation=False,training_started=False)
    for k,d in [('accepted_cases',report['cases']),('new_cases',report['cases']),('training_chat_rows',report['chat_rows']),('training_chat_rows_before_balancing',report['chat_rows']),('all_available_chat_rows_including_evaluation_and_audit',report['chat_rows'])]:state[k]+=d
    for k,counts in [('by_grade',report['by_grade']),('by_topic',report['by_topic'])]:
        for key,count in counts.items():state[k][key]=state[k].get(key,0)+count
    state.setdefault('sgk_finish_runs',[]).append(ref);state['current_drive_connection']=profile;state['updated_utc']=now
    state['status']='FINITE_SGK_GAP_APPEND_AND_FULL_ARCHIVE_PREPARATION_IN_PROGRESS';state['TRAINING_DATASET_READY']=False
    state['candidate_resolution_overlay']=dict(bundle_id=receipt['id'],member='data/release/candidate_resolution_overlay.json',sha256=sha((RUN/'release/candidate_resolution_overlay.json').read_bytes()))
    state['portable_data_resume']=dict(bundle_id=receipt['id'],checkpoint_member=ref['portable_checkpoint_member'],checkpoint_sha256=sha((RUN/'portable_resume/portable_checkpoint.json').read_bytes()),catalog_member=ref['discovered_catalog_member'],catalog_sha256=sha((RUN/'portable_resume/member_catalog_discovered.json').read_bytes()),account_specific_link_is_not_data_identity=True,code_member='code/math_data_portable_resume.py',full_archive_audit_complete=False)
    state['verified_legacy_source_hash_overlay']=dict(bundle_id=receipt['id'],manifest_member='data/source_hash_overlay/manifest.json',manifest_sha256=sha((RUN/'source_hash_overlay/manifest.json').read_bytes()),helper_member='code/math_data_source_hash_overlay.py',derived_missing_fields=3356,chat_associations_verified=3596,raw_old_payloads_unchanged=True,human_attestation_added=False)
    state['next_action']='Resume finite remaining mathematical subforms by exact candidate/master/hash; do not repeat accepted sources. Complete all source/chat member CPU token/linkage/split audit from portable queue. No training.'
    state['local_storage']['latest_run_staging']='BOUNDED_TEMPORARY_STAGING; prior cleanup denied by automatic policy, no retry or deletion claimed. New evidence authoritative on Drive after fresh raw verification.'
    chat.setdefault('supplement_bundles',[]).append(ref);chat['chat_rows']+=report['chat_rows'];chat['all_available_chat_rows_including_evaluation_and_audit']=state['all_available_chat_rows_including_evaluation_and_audit'];chat['current_drive_connection']=profile
    write(RUN/'publish_state.json',state);write(RUN/'publish_chat_manifest.json',chat)
    registry_path=HERE/'data/primary_math_teacher_20261016/drive_artifacts.json';registry=read(registry_path)
    if registry['account_identity'].get('profile_id')!=profile['profile_id']:registry.setdefault('account_identity_history',[]).append(registry['account_identity'])
    registry['account_identity']=profile;registry['link_id']=link_id;registry.setdefault('sgk_finish_append_bundles',[]).append(receipt);registry['connection_binding_verified_utc']=now
    registry['portable_resume_policy']='Immutable file IDs/hash identify data; resolve connector link dynamically. Mutable controls use same IDs. Alternate read access is not write permission. Never recreate folders/files on account switch.'
    write(registry_path,registry)
    context=HERE.parent/'MATH_TRAINING_CONTEXT.md';before=context.read_bytes();assert before==(RUN/'prewrite_context.md').read_bytes()
    text=before.decode('utf-8');marker='### Nhật ký20/10/2026 — sgk_finish_20261020 portable append'
    assert marker not in text
    portable=read(RUN/'portable_resume/final_status.json')
    text=re.sub(r'^<!-- CURRENT_CHECKPOINT[^\n]*-->\n','',text)
    header=f'<!-- CURRENT_CHECKPOINT sgk_finish_20261020: {state["accepted_cases"]} cases; {state["training_chat_rows"]} candidate chat; SGK and full archive preparation IN_PROGRESS; NO TRAINING. Latest journal supersedes historical counts. -->\n'
    note=f'''\n\n{marker}\nChủ yêu cầu tiếp tục, dùng agent phụ và tiếp nối được khi đổi tài khoản. Đã xác minh lại {profile['name']} profile{profile['profile_id']} qua connector hiện hành sau đổi tài khoản; raw STATE vẫn đúng hash063e95ed756b2824a30d9a76b3bc99da16b93beaea94d1864a9e6325e5e80411 trước append, không khởi tạo lại. Các profile đã đọc cùng một STATE ID/hash; không suy quyền sửa của profile còn lại từ quyền đọc. Data identity là ID/hash payload, không là link_id, tài khoản Codex hoặc thread/agent session. Portable task specs, lease/progress/results, catalog và SQLite evidence lưu trong gói mới; một coordinator cập nhật, không giả atomic lock nhiều người ghi Drive.\n\nNhận thêm {report['cases']} bài / {report['chat_rows']} chat sau đọc toàn bộ actual fields, QA7 và oracle/kiểm chéo đúng hash. Phân lớp {report['by_grade']}; {report['representation_master_count']} master có ví dụ mới, có nhánh dùng chung và giới hạn grade/modality. {report['numeric_steps']} bước Fraction/Decimal pass; token audit toàn bộ chat mới. {report['hash_numeric_exception_cases']} case có ngoại lệ numeric overlap đúng hash đã được chủ cho phép sau QA; không tuyên bố benchmark số học độc lập. Nhãn ACCEPTED_VALIDATED_OWNER_PREAUTHORIZED, không tự gán human review mới. Giữ tác giả/nguồn AI ban đầu, 299 human signoff, frozen/history và 495core/165node. G2 chat metadata nguồn được bổ sung bằng bản dẫn xuất, giữ bản trước sửa. G5 IDs kỹ thuật đã sửa có parent/delta, không đổi đáp án để qua gate.\n\nĐối chiếu liên lớp đã bảo toàn 204 labels/315 occurrences từ phạm vi đã rà, gộp167 masters: ban đầu63covered,94missing trong các nearest thực sự đọc,10asset-only;332nguồn train được đọc fullfield/hash. Những nhánh được nhận lần này và alias còn mở nằm trong candidate_resolution_overlay.json; không tự đóng G5 từ bài lớp1/3 hoặc coi merged là covered. QueueG2 91mục/65masters có14confirmedmasters được soạn,37merged/assetmasters còn cần xử lý.10tập/1220trang đã đọc, vẫn không tuyên bố đầy đủ mọi dạng SGK/pháp lý hoặc năng lực ảnh/thực hành.\n\nKiểm kho bằng CPU tokenizer pinned Qwen, khôngweights/train: actual {portable['tokenized_chat_rows']} chat đã kiểm trong các phần chọn thực sự chạy; {portable['candidate_train_chat_rows']} train candidate và {portable['pedagogy_current_eval_chat_rows_kept_separate']} eval sư phạm tách riêng. Đây không phải audit toàn {state['training_chat_rows']} candidatechat. 22 ZIP metadata directories đã đối chiếu,1928members/31payload IDs; partial Range metadata không chứng minh fresh toànZIP hash. {portable['historical_chat_missing_raw_source_hash_field']} legacychat thiếu field rawsourcehash được báo thật; nguồn/memberhash và liên kết actual fields được kiểm, không bịa field gốc. Portable queue {portable['finite_tasks']}tasks/{portable['complete_tasks']}complete/{portable['pending_tasks']}pending trước thêm công việc gói này. Không bỏ nguồn hợp lệ; balanced1256 chỉ diagnostic, uniontrain dùng mọi nguồn hợp lệ theo split và provenance đã kiểm. Fullarchive token/linkage/split audit còn pending.\n\nTổng quản lý {state['accepted_cases']} case, {state['training_chat_rows']} candidatechat; gồm eval/audit {state['all_available_chat_rows_including_evaluation_and_audit']}. CHƯA TRAIN. Gói mới {receipt['url']} SHA256 {receipt['sha256']}, {receipt['bytes']}bytes đã fresh raw so toàn byte/hash. Bốn control giữ đúng ID cũ; ưu tiên STATE hiện hành. Không tải toàn kho về máy, chỉ staging bounded. Lệnh dọn trước đã bị policy chặn; không thử lại hoặc tuyên bố đã dọn. Việc tiếp: các master còn mở và toàn kho CPU audit; không soạn lại case đã accepted.\n'''
    context.write_text(header+text+note,encoding='utf-8')
    with zipfile.ZipFile(RUN/'prewrite_progress.zip') as old,zipfile.ZipFile(RUN/'publish_progress_index.zip','w',zipfile.ZIP_DEFLATED,compresslevel=9) as new:
        for info in old.infolist():new.writestr(info,old.read(info.filename))
        files=[RUN/'release/audit_report.json',RUN/'release/token_audit.json',RUN/'release/candidate_resolution_overlay.json',RUN/'portable_resume/final_status.json',RUN/'bundle_remote_verified.json',RUN/'publish_state.json',RUN/'publish_chat_manifest.json']
        for p in files:new.writestr('sgk_finish_20261020/'+p.name,p.read_bytes())
        new.writestr('sgk_finish_20261020/MATH_TRAINING_CONTEXT.md',context.read_bytes());new.writestr('sgk_finish_20261020/drive_artifacts.json',registry_path.read_bytes())
    with zipfile.ZipFile(RUN/'prewrite_progress.zip') as old,zipfile.ZipFile(RUN/'publish_progress_index.zip') as new:assert not new.testzip() and all(old.read(n)==new.read(n) for n in old.namelist())
    print(json.dumps(dict(accepted=state['accepted_cases'],chat=state['training_chat_rows'],controls_staged=True)))
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--link-id',required=True);args=p.parse_args();main(args.link_id)
